css:
/* ================= 全局容器 ================= */
.mz-social-card {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  background: transparent;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.card-inner {
  width: 95%; height: 90%;
  border-radius: 28px;
  padding: 16px 20px;
  box-sizing: border-box;
  display: flex; flex-direction: column; justify-content: space-between;
  background: #ffffff; 
}

/* ================= 顶部个人信息 ================= */
.header-section {
  display: flex; justify-content: space-between; align-items: center;
}

.profile-left {
  display: flex; align-items: center; gap: 12px;
}

.main-avatar {
  position: relative;
  width: 56px; height: 56px;
}
.main-avatar img {
  width: 100%; height: 100%;
  border-radius: 18px;
  object-fit: cover;
}

.camera-icon {
  position: absolute; bottom: -2px; right: -4px;
  width: 20px; height: 20px;
  background: #000; color: #fff;
  border-radius: 50%; border: 2px solid #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px;
}

.info-text h2 {
  font-size: 19px; margin: 0;
  /* 增加 fallback 兜底：如果 JS 没传过来，默认 #333 */
  color: var(--text-col, #333333); font-weight: 700;
}
.info-text p {
  font-size: 13px; margin: 2px 0 0;
  color: var(--text-col, #333333); opacity: 0.6;
}

.btn-follow {
  padding: 8px 22px;
  background: var(--btn-bg, #cccccc);
  color: var(--btn-txt, #ffffff);
  border-radius: 20px;
  font-size: 14px; font-weight: 600;
}

/* ================= 底部圆圈列表 ================= */
.circle-row {
  display: flex; justify-content: space-between;
  padding: 0 4px;
}

/* 前5个圆的默认样式 */
.circle-item {
  width: 50px; height: 50px;
  border-radius: 50%;
  border: 1px solid rgba(0,0,0,0.08);
  overflow: hidden;
  display: flex; align-items: center; justify-content: center;
  background: rgba(0,0,0,0.03); 
}

/* 🌟 第6个圆专属底色 */
#lastCircle {
  background: var(--img6-bg, rgba(0,0,0,0.03));
}

.circle-item img {
  width: 100%; height: 100%;
  object-fit: cover;
}

/* ================= 加号样式 ================= */
.plus-icon {
  position: relative;
  width: 100%;
  height: 100%;
  color: transparent; 
}

.plus-icon::before,
.plus-icon::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%); 
  /* 🌟 核心：使用自定义加号颜色，如果没填则默认 #999 */
  background-color: var(--plus-color, #999999);
  border-radius: 1px; 
}

.plus-icon::before {
  width: 22px;   
  height: 1.5px; 
}

.plus-icon::after {
  width: 1.5px;  
  height: 22px;  
}
